; =====================================================================
; I2C master Z80 for the PC-1600, version 1.1 (speed lab version V10)
; Same interface as v1.0:  POKE &C5FC,D,W,R : CALL &C400,E  (see i2c_z80_v1.0.asm)
; SDA = page of the code + I register (A8 = pin 31), SCL = OPC bit 7 (pin 29), SDA read = PB2 (pin 27).
; Generated by tools/make_lab.py from the lab sources. 56 kHz in the ideal simulator; on the real
; PC-1600 about 43 kHz read / 54 kHz write: there every opcode fetch has one wait state and every
; I/O cycle one more (simulator option --real), so a prefixed instruction (ED, CB) costs 2 T more.
; Registers in the bit loops: B = SDA state (0/1, also the high address byte of OUT (C),r), C = 18h (OPC),
; D = 80h (SCL high), E = data byte, HL = buffer pointer; I = B.
; =====================================================================

HV      EQU 01h        ; I for the pages with A8 = 1 (SDA released)
LV      EQU 00h        ; I for the pages with A8 = 0 (SDA low)
OPC     EQU 18h         ; port: bit 7 -> SDO (pin 29, SCL), bit 6 -> buzzer (keep 0)
DDB     EQU 1Dh         ; port B direction (bit 2 = PB2 must be an input)
PBP     EQU 1Fh         ; port B data (bit 2 = SDA read back)

S_H1    EQU 81h         ; SCL = 1, A register bit 0 = 1 (A8 = 1)
S_L1    EQU 01h         ; SCL = 0, A8 = 1
S_H0    EQU 80h         ; SCL = 1, A8 = 0
S_L0    EQU 00h         ; SCL = 0, A8 = 0

RX      EQU 0C600h
TX      EQU 0C700h
CNT     EQU 0C5FBh
IA      EQU 0C5FCh
IW      EQU 0C5FDh
IR      EQU 0C5FEh
IS      EQU 0C5FFh

TXH     EQU 0C7h
RPT     EQU 0C5FAh
RCT     EQU 0C5F9h
        ORG 0C100h
WH:     LD A,S_H1
        OUT (OPC),A
        IN A,(PBP)
        LD D,A
        LD A,S_L1
        OUT (OPC),A
        RET
        ORG 0C120h
RH:     JP RH2
        ORG 0C140h
SH7:    BIT 7,E
        JP Z,TL7
SH7C:
        OUT (C),D
        OUT (C),B
SH6:    BIT 6,E
        JP Z,TL6
SH6C:
        OUT (C),D
        OUT (C),B
SH5:    BIT 5,E
        JP Z,TL5
SH5C:
        OUT (C),D
        OUT (C),B
SH4:    BIT 4,E
        JP Z,TL4
SH4C:
        OUT (C),D
        OUT (C),B
SH3:    BIT 3,E
        JP Z,TL3
SH3C:
        OUT (C),D
        OUT (C),B
SH2:    BIT 2,E
        JP Z,TL2
SH2C:
        OUT (C),D
        OUT (C),B
SH1:    BIT 1,E
        JP Z,TL1
SH1C:
        OUT (C),D
        OUT (C),B
SH0:    BIT 0,E
        JP Z,TL0
SH0C:
        OUT (C),D
        OUT (C),B
        JP ACKB
TL7:    DEC B
        LD A,B
        LD I,A
        JP SL7C
TL6:    DEC B
        LD A,B
        LD I,A
        JP SL6C
TL5:    DEC B
        LD A,B
        LD I,A
        JP SL5C
TL4:    DEC B
        LD A,B
        LD I,A
        JP SL4C
TL3:    DEC B
        LD A,B
        LD I,A
        JP SL3C
TL2:    DEC B
        LD A,B
        LD I,A
        JP SL2C
TL1:    DEC B
        LD A,B
        LD I,A
        JP SL1C
TL0:    DEC B
        LD A,B
        LD I,A
        JP SL0C
        ORG 0C1F5h
STH:    LD A,S_H1
        OUT (OPC),A
        NOP
        NOP
        NOP
        LD A,LV
        LD I,A
        ORG 0C200h
STT:    NOP
        NOP
        LD A,S_L0
        OUT (OPC),A
        RET
        ORG 0C210h
WL:     LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        RET
        ORG 0C220h
SL:     BIT 7,E
        JP NZ,TH7
SL7C:
        OUT (C),D
        OUT (C),B
        BIT 6,E
        JP NZ,TH6
SL6C:
        OUT (C),D
        OUT (C),B
        BIT 5,E
        JP NZ,TH5
SL5C:
        OUT (C),D
        OUT (C),B
        BIT 4,E
        JP NZ,TH4
SL4C:
        OUT (C),D
        OUT (C),B
        BIT 3,E
        JP NZ,TH3
SL3C:
        OUT (C),D
        OUT (C),B
        BIT 2,E
        JP NZ,TH2
SL2C:
        OUT (C),D
        OUT (C),B
        BIT 1,E
        JP NZ,TH1
SL1C:
        OUT (C),D
        OUT (C),B
        BIT 0,E
        JP NZ,TH0
SL0C:
        OUT (C),D
        OUT (C),B
        INC B
        LD A,B
        LD I,A
        JP ACKB
TH7:    INC B
        LD A,B
        LD I,A
        JP SH7C
TH6:    INC B
        LD A,B
        LD I,A
        JP SH6C
TH5:    INC B
        LD A,B
        LD I,A
        JP SH5C
TH4:    INC B
        LD A,B
        LD I,A
        JP SH4C
TH3:    INC B
        LD A,B
        LD I,A
        JP SH3C
TH2:    INC B
        LD A,B
        LD I,A
        JP SH2C
TH1:    INC B
        LD A,B
        LD I,A
        JP SH1C
TH0:    INC B
        LD A,B
        LD I,A
        JP SH0C
ACKL:
        OUT (C),D
        OUT (C),B
        INC B
        LD A,B
        LD I,A
        JP RDB1
        ORG 0C2F5h
STL:    LD A,S_H0
        OUT (OPC),A
        NOP
        NOP
        NOP
        LD A,HV
        LD I,A
        ORG 0C300h
STP2:   NOP
        NOP
        NOP
        LD A,S_L1
        OUT (OPC),A
        RET
        ORG 0C310h
RH2:
RDB1:
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        OUT (C),D
        LD A,B
        IN A,(PBP)
        OUT (C),B
        RRA
        RRA
        RRA
        RL E
        LD (HL),E
        INC HL
        LD A,(IR)
        CP L
        JP Z,LASTB
        DEC B
        LD A,B
        LD I,A
        JP ACKL
LASTB:  OUT (C),D
        OUT (C),B
        RET
ACKB:   OUT (C),D
        LD A,B
        IN A,(PBP)
        BIT 2,A
        JP NZ,NAKB
        OUT (C),B
        LD A,(IW)
        CP L
        JP Z,DONEB
        LD E,(HL)
        INC HL
        JP SH7
NAKB:   OUT (C),B
        LD D,4
        RET
DONEB:  LD D,0
        RET

        ORG 0C400h
IC:     LD A,S_L1
        OUT (OPC),A             ; SCL low at once: from here on A8 may chop
        LD A,I
        JP PE,IC1               ; P/V = IFF2 = 1: believed at once
        LD A,I                  ; 0 is read twice (an interrupt during LD A,I of an NMOS Z80
                                ; gives P/V = 0 although the interrupts are enabled, and the
                                ; EI at the exit would be lost)
IC1:    PUSH AF                 ; I and IFF2 (P/V flag)
        DI
        IN A,(DDB)
        AND 0FBh
        OUT (DDB),A             ; PB2 = input
        XOR A
        LD (IS),A
        CALL BUSCHK
        JP C,E3
        LD A,(IW)
        OR A
        JR NZ,DOWR
        LD A,(IR)
        OR A
        JR NZ,DORD              ; W = 0, R > 0: read at once
DOWR:   CALL START
        LD A,(IA)
        ADD A,A
        LD C,A                  ; address, write bit = 0
        CALL SENDB
        BIT 2,D
        JP NZ,E1                ; no ACK
        LD A,(IW)
        OR A
        JR Z,AFTW
        CALL WRBLK
        BIT 2,D
        JP NZ,E2
AFTW:   LD A,(IR)
        OR A
        JR Z,DOSTOP
DORD:   CALL START              ; (repeated) START
        LD A,(IA)
        ADD A,A
        INC A
        LD C,A                  ; address, read bit = 1
        CALL SENDB
        BIT 2,D
        JP NZ,E1
        CALL RDB
DOSTOP: CALL STOP
EXIT:   POP AF
        LD I,A                  ; I restored (flags are not changed)
        JP PO,EX2               ; P/V = IFF2: interrupts were off
        EI
EX2:    LD A,(IS)
        LD E,A
        LD D,0
        SCF                     ; CALL IC,E returns the result in E
        RET
E1:     LD A,1
        JR ERR
E2:     LD A,2
ERR:    LD (IS),A
        CALL STOP
        JR EXIT
E3:     LD A,3
        LD (IS),A
        JR EXIT

BUSCHK: LD A,HV                 ; up to 10 clocks until SDA is high
        LD I,A
        LD B,10
BC1:    CALL WH
        BIT 2,D
        JR NZ,BCOK
        DJNZ BC1
        SCF                     ; SDA stuck low
        RET
BCOK:   OR A
        RET

START:  LD A,HV
        LD I,A
        JP STH
STOP:   LD A,LV
        LD I,A
        JP STL
SENDB:  LD E,C
        LD A,(IW)
        LD L,A
        LD H,TXH
        LD BC,0018h
        LD D,80h
        LD A,LV
        LD I,A
        JP SL
WRBLK:  LD HL,TX
        LD E,(HL)
        INC HL
        LD BC,0118h
        LD D,80h
        LD A,HV
        LD I,A
        JP SH7
RDB:    LD HL,RX
        LD BC,0118h
        LD D,80h
        LD A,HV
        LD I,A
        JP RDB1

; ---------------------------------------------------------------------
; C560: empty routine (the BASIC program times it to subtract the time of the BASIC CALL itself)
; C580: REP, calls the driver K times (K = byte at C5FA) and stops at an error. The BMP280 program
;       uses it to measure the I2C speed; the interrupts stay enabled between the transfers.
; ---------------------------------------------------------------------
        ORG 0C560h
BR:     RET
        ORG 0C580h
REP:    LD A,(RPT)
        LD (RCT),A
RP1:    CALL IC
        LD A,E
        OR A
        JR NZ,RP2
        LD A,(RCT)
        DEC A
        LD (RCT),A
        JR NZ,RP1
RP2:    RET
